/**
 * What a notification's one button does, decided from the message alone.
 *
 * Three kinds of button, one look (design `uiux/2026-10-21-notification-actions`
 * §2.3): a screen of the app, a form, or a web page in the system browser. A
 * form already answered or closed shows a line instead of a button. A link
 * whose address fails the check here shows that it cannot be opened, and is
 * never drawn as a link. A message with nothing to open shows nothing.
 */
import type { InboxNotification } from '@/db/schema.js';
import { t, type MessageKey } from '@/i18n/index.js';
import { safeNotificationUrl } from '@/lib/externalLinks.js';
import { inAppPath, PUSH_FALLBACK_PATH } from '@/lib/platform/pushLink.js';
import { isOfferPath } from '@/features/billing/offerLink.js';

export type ActionView =
  | { kind: 'none' }
  /** A screen or a form inside the app. */
  | { kind: 'open'; path: string; label: string }
  | { kind: 'answered' }
  | { kind: 'closed' }
  /** A checked address, opened in the system browser on a press. */
  | { kind: 'link'; href: string; host: string; label: string }
  /** A link that failed the check: said, never drawn as a link. */
  | { kind: 'blocked' }
  /** A link while the server has not said which hosts are allowed yet. */
  | { kind: 'waiting' };

/** The screens a path may name, by their first segment, for "Open {screen}". */
const SCREENS: Partial<Record<string, MessageKey>> = {
  notebook: 'nav.notebook',
  words: 'nav.notebook',
  progress: 'nav.progress',
  settings: 'nav.settings',
  decks: 'nav.decks',
  games: 'nav.games',
  assistant: 'nav.ai',
};

/** "Open Progress" for /progress; plain "Open" for a path with no screen name. */
export function openLabel(path: string): string {
  // The offer's deep link says what it opens (`billing/offerLink.ts`).
  if (isOfferPath(path)) return t('inbox.openOffer');
  const segment = path.split(/[/?#]/)[1] ?? '';
  const screen = SCREENS[segment];
  return screen === undefined ? t('inbox.open') : t('inbox.openScreen', { screen: t(screen) });
}

/** The path a tap on the message opens: the server's tapPath, or an older copy's link. */
export function tapPathOf(item: Pick<InboxNotification, 'tapPath' | 'link'>): string {
  return inAppPath(item.tapPath ?? item.link ?? PUSH_FALLBACK_PATH);
}

/**
 * The button a message shows. `hosts` is `ClientConfig.linkHosts`;
 * `hostsKnown` is whether the server has answered (or failed to), so a link
 * is not called unopenable in the moment before the list arrives.
 */
export function actionView(
  item: Pick<InboxNotification, 'tapPath' | 'link' | 'action'>,
  hosts: readonly string[] | undefined,
  hostsKnown: boolean,
): ActionView {
  const action = item.action;
  if (action?.type === 'form') {
    if (action.answered === true) return { kind: 'answered' };
    if (action.open === false) return { kind: 'closed' };
    const path =
      action.formId === undefined
        ? tapPathOf(item)
        : inAppPath(`/forms/${encodeURIComponent(action.formId)}`);
    if (path === PUSH_FALLBACK_PATH) return { kind: 'none' };
    return { kind: 'open', path, label: action.label ?? t('inbox.openForm') };
  }
  if (action?.type === 'url') {
    if (action.url === undefined) return { kind: 'blocked' };
    if (!hostsKnown) return { kind: 'waiting' };
    const url = safeNotificationUrl(action.url, hosts);
    if (url === undefined) return { kind: 'blocked' };
    return { kind: 'link', href: url.href, host: url.hostname, label: action.label ?? t('inbox.openLink') };
  }
  const path = tapPathOf(item);
  if (path === PUSH_FALLBACK_PATH) return { kind: 'none' };
  return { kind: 'open', path, label: openLabel(path) };
}
