import { Icon } from '@/components/ui/Icon.js';
import { dirOf } from '@/features/assistant/richText.js';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { platform } from '@/lib/platform/index.js';
import type { ActionView } from './action.js';
import styles from './NotificationAction.module.css';

/**
 * A notification's one button, or the line that stands in for it
 * (design §2.2–2.3). The only control on its card: the card itself is no
 * longer pressable, so there are never two targets doing one thing.
 *
 * A link is an `<a>` to the checked address, so it reads and behaves as a
 * link, and a press hands it to the system browser through
 * `platform.openExternal`, never the app's own window. The address was
 * checked against the server's list just before it was drawn
 * (`actionView`); nothing is added to it.
 */
export function NotificationAction({
  view,
  onOpen,
}: {
  view: ActionView;
  /** Opens an in-app path (closing whatever sheet holds the button). */
  onOpen: (path: string) => void;
}): React.JSX.Element | null {
  switch (view.kind) {
    case 'none':
    case 'waiting':
      return null;
    case 'answered':
      return (
        <div className={styles.action}>
          <span className={styles.done}>
            <Icon name="check" size={16} weight={2.2} />
            {t('inbox.answered')}
          </span>
        </div>
      );
    case 'closed':
      return (
        <div className={styles.action}>
          <span className={styles.ended}>{t('inbox.formClosed')}</span>
        </div>
      );
    case 'blocked':
      return (
        <div className={styles.action}>
          <span className={styles.ended}>{t('inbox.linkBlocked')}</span>
        </div>
      );
    case 'open':
      return (
        <div className={styles.action}>
          <button
            type="button"
            className={styles.button}
            onClick={() => {
              onOpen(view.path);
            }}
          >
            <span className={styles.label} dir="auto">
              {view.label}
            </span>
            <span className={cx(styles.icon, dirOf(view.label) === 'rtl' && styles.flip)}>
              <Icon name="arrowRight" size={16} weight={2} />
            </span>
          </button>
        </div>
      );
    case 'link':
      return (
        <div className={styles.action}>
          <a
            className={styles.button}
            href={view.href}
            target="_blank"
            rel="noopener noreferrer"
            onClick={(event) => {
              event.preventDefault();
              platform.openExternal(view.href);
            }}
          >
            <span className={styles.label} dir="auto">
              {view.label}
            </span>
            <span className={cx(styles.icon, dirOf(view.label) === 'rtl' && styles.flip)}>
              <Icon name="external" size={16} weight={2} />
            </span>
            <span className="sr-only"> {t('inbox.opensInBrowser')}</span>
          </a>
          <span className={styles.dest} aria-hidden="true">
            {view.host}
          </span>
        </div>
      );
  }
}
